const src = $json.output || $json;
const f = $('Plant Photo Form').item.json;
const bullets = function (x) { return Array.isArray(x) ? x.map(function (i) { return '- ' + i; }).join('\n') : (x || ''); };
const join = function (x) { return Array.isArray(x) ? x.join('; ') : (x || ''); };
const days = Number(src.water_every_days) || 7;
const next = new Date(Date.now() + days * 86400000).toISOString().slice(0, 10);
return {
  email: f['Your email'] || '',
  nickname: f.Nickname || '',
  location: f.Location || '',
  commonName: src.common_name || 'Unknown',
  scientificName: src.scientific_name || '',
  confidence: String(src.confidence || 'low').toLowerCase(),
  health: String(src.health || 'healthy').toLowerCase(),
  problems: join(src.problems),
  problemList: bullets(src.problems),
  watering: src.watering || '',
  light: src.light || '',
  careTips: bullets(src.care_tips),
  waterEveryDays: days,
  nextWatering: next,
  toxicToPets: src.toxic_to_pets ? 'Yes' : 'No'
};
